sealed class BlockRecord {
    public readonly Block block;
    public readonly BlockRecord parent;
    public readonly Dictionary<Reference, Coin> utxo;
    public readonly List<int> transactionFees;
    public readonly string source;
    public readonly int fees, work;
    public BlockRecord(Block block, BlockRecord parent, Dictionary<Reference, Coin> utxo,
                       List<int> transactionFees, string source) {
        this.block = block;
        this.parent = parent;
        this.utxo = utxo;
        this.transactionFees = transactionFees;
        this.source = source;
        fees = transactionFees.Sum();
        work = parent == null ? 1 : parent.work + (1 << (4 * block.difficulty));
    }
    public static BlockRecord Ancestor(BlockRecord record, int height) {
        while (record.block.height > height)
            record = record.parent;
        return record;
    }
    public static List<BlockRecord> Sequence(BlockRecord record) {
        List<BlockRecord> records = new();
        while (record != null) {
            records.Add(record);
            record = record.parent;
        }
        records.Reverse();
        return records;
    }
    public static BlockRecord Fork(BlockRecord first, BlockRecord second) {
        int height = Math.Min(first.block.height, second.block.height);
        first = Ancestor(first, height);
        second = Ancestor(second, height);
        while (first != second) {
            first = first.parent;
            second = second.parent;
        }
        return first;
    }
sealed class Block {
    public readonly int height, timestamp, difficulty, nonce;
    public readonly string previous, merkle, hash;
    public readonly List<Transaction> transactions;
    public Block(int height, string previous, string merkle, int timestamp, int difficulty, int nonce,
                 List<Transaction> transactions) {
        this.height = height;
        this.previous = previous;
        this.merkle = merkle;
        this.timestamp = timestamp;
        this.difficulty = difficulty;
        this.nonce = nonce;
        this.transactions = transactions;
        hash = Hashing.Digest(Blocks.Header(height, previous, merkle, timestamp, difficulty, nonce));
    }
    public int Size() {
        int size = 0;
        foreach (Transaction transaction in transactions.GetRange(1, transactions.Count - (1)))
            size += transaction.Size();
        return size;
    }
    public List<string> Txids() {
        return transactions.Select(transaction => transaction.txid).ToList();
    }
}
static class Blocks {
    public static string Header(int height, string previous, string merkle, int timestamp, int difficulty,
                                int nonce) {
        return height + "|" + previous + "|" + merkle + "|" + timestamp + "|" + difficulty + "|" + nonce;
    }
    public static Block Parse(string[] fields, List<string> texts) {
        return new Block(int.Parse(fields[3]), fields[4], fields[5], int.Parse(fields[6]),
                         int.Parse(fields[7]), int.Parse(fields[8]),
                         texts.Select(Transactions.Parse).ToList());
    }
    public static string Error(Block block, int maximum) {
        if (!block.hash.StartsWith(new string('0', block.difficulty)))
            return "bad-pow";
        if (!Hashing.Merkle(block.Txids()).Equals(block.merkle))
            return "bad-merkle";
        Transaction first = block.transactions[0];
        if (!first.Coinbase() || first.coinbaseHeight != block.height)
            return "bad-structure";
        foreach (Transaction transaction in block.transactions.GetRange(1, block.transactions.Count - (1)))
            if (transaction.Coinbase())
                return "bad-structure";
        return block.Size() > maximum ? "too-large" : null;
    }
sealed record Reference(string txid, int index) : IComparable<Reference> {
    public int CompareTo(Reference other) {
        int order = string.CompareOrdinal(txid, other.txid);
        return order != 0 ? order : index.CompareTo(other.index);
    }
    public override string ToString() {
        return txid + ":" + index;
    }
}
sealed record Coin(string address, int amount, int height, bool coinbase) {
    public bool Mature(int at, int maturity) {
        return !coinbase || height == 0 || at >= height + maturity;
    }
}
sealed record Check(string reason, int fee);
    public bool Coinbase() {
        return coinbaseHeight != null;
    }
    public int Size() {
        return text.Length;
    }
    public int Total() {
        int total = 0;
        foreach (Payment output in outputs)
            total += output.amount;
        return total;
    }
    public static Check Check(Transaction transaction, Dictionary<Reference, Coin> utxo,
                              HashSet<Reference> spent, int height, Dictionary<string, Wallet> owners,
                              int maturity) {
        foreach (Payment output in transaction.outputs)
            if (!owners.ContainsKey(output.address) || output.amount == 0)
                return new Check("bad-output", 0);
        HashSet<Reference> seen = new();
        int total = 0;
        for (int i = 0; i < transaction.inputs.Count; i++) {
            Reference reference = transaction.inputs[i];
            if (spent.Contains(reference) || seen.Contains(reference))
                return new Check("double-spend", 0);
            utxo.TryGetValue(reference, out Coin coin);
            if (coin == null)
                return new Check("missing-input", 0);
            if (!coin.Mature(height, maturity))
                return new Check("immature", 0);
            if (!transaction.signatures[i].Equals(
                    Wallets.Sign(owners[coin.address].secret, i, transaction.body)))
                return new Check("bad-sig", 0);
            seen.Add(reference);
            total += coin.amount;
        }
        return total < transaction.Total() ? new Check("overspend", 0)
                                           : new Check(null, total - transaction.Total());
    }
    public static void Apply(Dictionary<Reference, Coin> utxo, Transaction transaction, int height) {
        foreach (Reference reference in transaction.inputs)
            utxo.Remove(reference);
        for (int i = 0; i < transaction.outputs.Count; i++) {
            Payment output = transaction.outputs[i];
            utxo[new Reference(transaction.txid, i)] =
                new Coin(output.address, output.amount, height, transaction.Coinbase());
        }
    }
